def solve():
    mcap = {"A": Fraction(P["MCAP_A"]), "B": Fraction(300), "C": Fraction(250), "D": Fraction(200), "E": Fraction(150)}
    rev = {"A": Fraction(0), "B": Fraction(P["REV_B"]), "C": Fraction(5), "D": Fraction(P["REV_D"]), "E": Fraction(0)}
    capex = {"A": Fraction(0), "B": Fraction(P["CAPEX_B"]), "C": Fraction(0), "D": Fraction(12), "E": Fraction(0)}
    thresh = Fraction(P["THRESH"])
    exempt_min = Fraction(P["EXEMPT_MIN"])
    cap_mult = Fraction(str(P["CAP_MULT"]))
    retained = []
    excluded = 0
    for k in ["A", "B", "C", "D", "E"]:
        if rev[k] > thresh and capex[k] < exempt_min:
            excluded += 1
        else:
            retained.append(k)
    n = len(retained)
    if n == 0:
        raise ValueError("no issuers retained")
    total = sum(mcap[k] for k in retained)
    w = {k: mcap[k] / total * 100 for k in retained}
    cap = cap_mult * Fraction(100, n)
    capped = [k for k in retained if w[k] > cap]
    uncapped = [k for k in retained if w[k] <= cap]
    if len(capped) > 0 and len(uncapped) == 0:
        raise ValueError("no recipients for excess")
    excess = sum(w[k] - cap for k in capped)
    base = sum(w[k] for k in uncapped)
    final = {}
    for k in retained:
        if k in capped:
            final[k] = cap
        else:
            final[k] = w[k] + (excess * w[k] / base if excess > 0 else Fraction(0))
    largest = max(final.values())
    c_final = final["C"]
    return {"final": c_final, "excluded_count": Fraction(excluded), "cap_level": cap, "redistributed_excess": excess, "largest_final_weight": largest}
